// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // fuzz the boolean that controls whether the helper reverts or not
    function testFuzz_property(bool calleeReverts) public {
        // deploy a helper that either reverts or succeeds based on the input
        ReverterOrSucceeder helper = new ReverterOrSucceeder(c);

        // configure helper mode via its public setter
        helper.setShouldRevert(calleeReverts);

        // Call c.forward with helper address. We observe whether c.forward reverts or not.
        bool ok;
        try c.forward(address(helper), "") {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): For the reference contract, forward should succeed iff
        // the callee low-level call succeeded. Our helper makes the low-level call succeed when
        // calleeReverts == false, and makes it revert when calleeReverts == true. Therefore
        // the reference satisfies: ok == (!calleeReverts) for ALL inputs. The mutant inverts
        // the success flag and will violate this for at least one value (both values in fact).
        assertTrue(ok == (!calleeReverts));
    }
}

// Helper that either reverts on receive/fallback or accepts the call, controlled by a flag.
contract ReverterOrSucceeder {
    bool public shouldRevert;
    Proxy public parent;

    constructor(Proxy _c) {
        parent = _c;
    }

    function setShouldRevert(bool v) public {
        shouldRevert = v;
    }

    // fallback to match C's low-level call form; revert or accept depending on flag.
    fallback() external payable {
        if (shouldRevert) {
            revert("helper revert");
        }
        // otherwise do nothing (succeed)
    }

    receive() external payable {
        if (shouldRevert) {
            revert("helper revert");
        }
    }
}
